const PENDING_STORAGE='avanti-pending-cost-decisions-v1';
const pendingView={status:'pending',reason:'',query:'',page:0,selectedKey:'',candidateQuery:'',mode:'cost_gtin'};
let pendingDecisions={};
try{const saved=JSON.parse(localStorage.getItem(PENDING_STORAGE)||'{}');pendingDecisions=saved&&typeof saved==='object'&&!Array.isArray(saved)?saved:{}}catch(_){pendingDecisions={}}
function savePendingDecisions(){localStorage.setItem(PENDING_STORAGE,JSON.stringify(pendingDecisions))}

function pendingBaseRows(){
  if(!analytics.comparable)return [];
  if(!analytics.costIndex)analytics.costIndex=AC.costIndex(state.costs,costUnitDecisions);
  return AC.attachCosts(analytics.data,analytics.costIndex,true).filter(row=>row.cost==null);
}
function pendingGroups(){
  const index=analytics.costIndex||(analytics.costIndex=AC.costIndex(state.costs,costUnitDecisions));
  return AvantiPendingReview.groups(pendingBaseRows(),AC.normalize).map(group=>{
    const decision=pendingDecisions[group.key]||null,evaluation=AvantiPendingReview.evaluate(group,decision,index,AC);
    return {...group,decision,...evaluation};
  });
}
function pendingStatusLabel(group){return group.state==='resolved'?'Resuelto':group.state==='partial'?'Cobertura parcial':group.state==='excluded'?'Exclusión verificada':'Pendiente'}
function pendingStatusClass(group){return group.state==='resolved'?'':group.state==='excluded'?'calc':'bonus'}
function pendingCostCatalog(){
  const index=analytics.costIndex||(analytics.costIndex=AC.costIndex(state.costs,costUnitDecisions));
  const source=state.purchases?.catalog||[];
  if(source.length)return source.filter(item=>index.has(String(item.gtin)));
  const uniqueGtins=new Map();
  for(const row of state.costs.detail)if(row.gtin&&index.has(String(row.gtin))&&!uniqueGtins.has(String(row.gtin)))uniqueGtins.set(String(row.gtin),{gtin:String(row.gtin),systemName:row.systemName||row.description,catalogNames:[row.description],providers:[row.provider]});
  return [...uniqueGtins.values()];
}
function pendingGroupByKey(key){return pendingGroups().find(group=>group.key===key)}

function renderPendingDecision(){
  const dialog=$('#pendingDecisionDialog'),group=pendingGroupByKey(pendingView.selectedKey);if(!dialog||!group)return;
  const current=pendingDecisions[group.key]||{},mode=pendingView.mode||current.mode||'cost_gtin';
  const candidates=mode==='cost_gtin'?AvantiPurchaseMatching.rank(group.product,pendingCostCatalog(),pendingView.candidateQuery,14):[];
  dialog.innerHTML=`<button class="dialog-close" id="closePendingDecision" aria-label="Cerrar">×</button><p class="eyebrow">CORRECCIÓN TEMPORAL</p><h2 id="pendingDecisionTitle">${esc(group.product)}</h2><p><span class="mono">${esc(group.code||'Sin código')}</span> · ${quantity(group.rows.length)} líneas · ${money(group.amount)}<br>${esc(group.reason)}</p>
    <label class="unit-decision-label">Tipo de resolución<select id="pendingMode"><option value="cost_gtin" ${mode==='cost_gtin'?'selected':''}>Relacionar con un GTIN que tenga costo</option><option value="manual_cost" ${mode==='manual_cost'?'selected':''}>Ingresar costo unitario confirmado</option><option value="exclude" ${mode==='exclude'?'selected':''}>Excluir del margen con justificación</option></select></label>
    ${mode==='cost_gtin'?`<input class="candidate-search" id="pendingCandidateSearch" type="search" value="${esc(pendingView.candidateQuery)}" placeholder="Buscar por nombre o GTIN…" autocomplete="off"><div class="candidate-list">${candidates.map(candidate=>{const history=analytics.costIndex.get(String(candidate.gtin))||[];return `<article class="candidate-card"><div class="candidate-main"><b>${esc(candidate.systemName||candidate.catalogNames?.[0]||'Producto de costos')}</b><small><span class="mono">${esc(candidate.gtin)}</span> · Costos disponibles: ${history.map(item=>item.month).join(', ')}</small><div class="candidate-meta"><span class="candidate-score">${Math.round(candidate.score*100)}% semejanza</span>${matchBadges(candidate)}</div></div><button class="btn" data-pending-gtin="${esc(candidate.gtin)}">Usar este costo</button></article>`}).join('')||'<div class="candidate-empty">No hay un GTIN con costo disponible para esta búsqueda.</div>'}</div>`:''}
    ${mode==='manual_cost'?`<label class="unit-decision-label">Costo final por unidad, con IGV<input id="pendingManualCost" type="number" min="0.0001" step="0.0001" value="${esc(current.mode==='manual_cost'?current.unitCost:'')}" placeholder="Ejemplo: 1.2500"></label><label class="unit-decision-label">Fuente que respalda el costo<input id="pendingSource" value="${esc(current.source||'')}" placeholder="Factura, cotización o maestro"></label><label class="unit-decision-label">Observación<input id="pendingNote" value="${esc(current.note||'')}" placeholder="Detalle opcional"></label><div class="purchase-actions"><button class="btn" id="savePendingManual">Guardar costo</button></div>`:''}
    ${mode==='exclude'?`<label class="unit-decision-label">Justificación<select id="pendingExclusion"><option value="">Selecciona…</option>${['Accesorio médico no gestionado','Ajuste o devolución','Proveedor no oficial','Producto descontinuado','No corresponde a una venta comparable'].map(value=>`<option ${current.exclusion===value?'selected':''}>${value}</option>`).join('')}</select></label><label class="unit-decision-label">Observación<input id="pendingNote" value="${esc(current.note||'')}" placeholder="Explica por qué no debe tener margen"></label><div class="purchase-actions"><button class="btn" id="savePendingExclusion">Guardar exclusión</button></div>`:''}
    ${current.mode?'<div class="purchase-actions pending-remove"><button class="btn secondary" id="removePendingDecision">Quitar decisión guardada</button></div>':''}`;
  $('#closePendingDecision').onclick=()=>dialog.close();
  $('#pendingMode').onchange=e=>{pendingView.mode=e.target.value;pendingView.candidateQuery='';renderPendingDecision()};
  if($('#pendingCandidateSearch'))$('#pendingCandidateSearch').oninput=e=>{const caret=e.target.selectionStart;pendingView.candidateQuery=e.target.value;renderPendingDecision();$('#pendingCandidateSearch').focus();$('#pendingCandidateSearch').setSelectionRange(caret,caret)};
  document.querySelectorAll('[data-pending-gtin]').forEach(button=>button.onclick=()=>{const target=pendingCostCatalog().find(item=>String(item.gtin)===button.dataset.pendingGtin);if(!target)return;pendingDecisions[group.key]={mode:'cost_gtin',targetGtin:String(target.gtin),targetName:target.systemName||target.catalogNames?.[0]||'',product:group.product,code:group.code,reason:group.reason,savedAt:new Date().toISOString()};savePendingDecisions();dialog.close();renderPendingReview()});
  if($('#savePendingManual'))$('#savePendingManual').onclick=()=>{const unitCost=Number($('#pendingManualCost').value),source=$('#pendingSource').value.trim();if(!(unitCost>0))return alert('Indica un costo unitario mayor que cero.');if(!source)return alert('Indica la factura, cotización o maestro que respalda el costo.');pendingDecisions[group.key]={mode:'manual_cost',unitCost,source,note:$('#pendingNote').value.trim(),product:group.product,code:group.code,reason:group.reason,savedAt:new Date().toISOString()};savePendingDecisions();dialog.close();renderPendingReview()};
  if($('#savePendingExclusion'))$('#savePendingExclusion').onclick=()=>{const exclusion=$('#pendingExclusion').value,note=$('#pendingNote').value.trim();if(!exclusion)return alert('Selecciona una justificación.');pendingDecisions[group.key]={mode:'exclude',exclusion,note,product:group.product,code:group.code,reason:group.reason,savedAt:new Date().toISOString()};savePendingDecisions();dialog.close();renderPendingReview()};
  if($('#removePendingDecision'))$('#removePendingDecision').onclick=()=>{delete pendingDecisions[group.key];savePendingDecisions();dialog.close();renderPendingReview()};
}
function openPendingDecision(key){pendingView.selectedKey=key;pendingView.candidateQuery='';pendingView.mode=pendingDecisions[key]?.mode||'cost_gtin';renderPendingDecision();$('#pendingDecisionDialog').showModal()}

function exportPendingJson(groups){
  const totalRows=groups.reduce((sum,g)=>sum+g.rows.length,0),verifiedRows=groups.filter(g=>g.verified||g.state==='excluded').reduce((sum,g)=>sum+g.rows.length,0);
  const payload={version:1,type:'avanti_pending_cost_corrections',exportedAt:new Date().toISOString(),salesSource:analytics.meta?.source||'',summary:{groups:groups.length,rows:totalRows,verifiedGroups:groups.filter(g=>g.verified||g.state==='excluded').length,verifiedRows},decisions:Object.fromEntries(Object.entries(pendingDecisions).filter(([key])=>groups.some(group=>group.key===key)))};
  const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));link.download=`correcciones_costos_pendientes_${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(link.href);
}
function exportPendingExcel(groups){
  const matrix=[['clave','codigo_venta','producto','unidad','motivo_original','lineas','importe_vendido','meses','estado','tipo_decision','gtin_costo_destino','producto_costo_destino','costo_unitario_manual','fuente','justificacion','observacion','fecha_decision'],...groups.map(g=>[g.key,g.code,g.product,g.unit,g.reason,g.rows.length,g.amount,g.months.join(', '),pendingStatusLabel(g),g.decision?.mode||'',g.decision?.targetGtin||'',g.decision?.targetName||'',g.decision?.unitCost??'',g.decision?.source||'',g.decision?.exclusion||'',g.decision?.note||'',g.decision?.savedAt||''])];
  downloadWorkbook('revision_temporal_30_porciento.xlsx',matrix,'Pendientes de costo',[['Criterio','Valor'],['Uso','Cola temporal de ventas sin costo comparable'],['Relacionar GTIN','Usa únicamente GTIN con costo disponible en la BD madre.'],['Costo manual','Debe ser costo final por unidad con IGV y registrar su fuente.'],['Exclusión','Cierra la verificación, pero no crea un margen.'],['Reintegración','Entregar el JSON exportado para validar, centralizar las decisiones y retirar este apartado temporal.']]);
}

function renderPendingReview(){
  if(analytics.loading)return content.innerHTML='<div class="empty"><b>Cargando ventas y costos…</b></div>';
  if(!analytics.comparable)return content.innerHTML='<div class="empty"><b>Primero confirma la unidad e IGV de ventas</b>Abre “Precios y cantidades” y habilita la comparación antes de revisar pendientes.</div>';
  const groups=pendingGroups(),reasons=unique(groups.map(group=>group.reason)).sort(),q=AC.normalize(pendingView.query);
  const evaluated=groups.filter(group=>(!pendingView.reason||group.reason===pendingView.reason)&&(!q||AC.normalize([group.code,group.product,group.reason].join(' ')).includes(q)));
  const filtered=evaluated.filter(group=>pendingView.status==='all'||(pendingView.status==='verified'?(group.verified||group.state==='excluded'):pendingView.status==='partial'?group.state==='partial':group.state==='pending'));
  const rank={pending:0,partial:1,excluded:2,resolved:3};filtered.sort((a,b)=>(rank[a.state]??9)-(rank[b.state]??9)||b.amount-a.amount);
  const pages=Math.max(1,Math.ceil(filtered.length/40));pendingView.page=Math.min(pendingView.page,pages-1);const page=filtered.slice(pendingView.page*40,(pendingView.page+1)*40);
  const totalRows=groups.reduce((sum,g)=>sum+g.rows.length,0),totalAmount=groups.reduce((sum,g)=>sum+g.amount,0),verified=groups.filter(g=>g.verified||g.state==='excluded'),verifiedRows=verified.reduce((sum,g)=>sum+g.rows.length,0),coveredRows=groups.reduce((sum,g)=>sum+g.coveredRows,0);
  content.innerHTML=`<div class="view"><div class="section-head"><div><p class="eyebrow">APARTADO TEMPORAL</p><h2>30% pendiente de verificar</h2><p>Solo aparecen ventas que todavía no tienen un costo comparable.</p></div><div class="purchase-actions"><button class="btn secondary" id="exportPendingJson">Exportar correcciones JSON</button><button class="btn secondary" id="exportPendingExcel">Exportar control Excel</button></div></div>
    <div class="cost-note"><b>Objetivo:</b> resolver cada grupo relacionándolo con un GTIN que ya tenga costo, ingresando un costo unitario confirmado o documentando una exclusión. Las decisiones se guardan en este navegador. Cuando el indicador de verificación llegue a 100%, exporta el JSON y envíamelo para centralizarlo y retirar este apartado.</div>
    <section class="kpis">${kpi('!',quantity(totalRows),'Líneas originales pendientes',money(totalAmount))}${kpi('▤',quantity(groups.length),'Grupos por revisar','código/producto + motivo')}${kpi('✓',percentage(groups.length?verified.length/groups.length:1),'Verificación completada',`${quantity(verifiedRows)} líneas revisadas`)}${kpi('S/',quantity(coveredRows),'Líneas con costo recuperado','exclusiones no suman')}</section>
    <div class="pending-progress"><div style="width:${groups.length?verified.length/groups.length*100:100}%"></div></div>
    <div class="analytics-filters pending-filters"><label>Estado<select id="pendingStatus"><option value="pending" ${pendingView.status==='pending'?'selected':''}>Pendientes</option><option value="partial" ${pendingView.status==='partial'?'selected':''}>Cobertura parcial</option><option value="verified" ${pendingView.status==='verified'?'selected':''}>Verificados</option><option value="all" ${pendingView.status==='all'?'selected':''}>Todos</option></select></label><label>Motivo<select id="pendingReason"><option value="">Todos</option>${reasons.map(reason=>`<option ${pendingView.reason===reason?'selected':''}>${esc(reason)}</option>`).join('')}</select></label><label class="analytics-search">Código o producto<input id="pendingQuery" type="search" value="${esc(pendingView.query)}" placeholder="Buscar pendiente…"></label><button class="btn secondary" id="pendingClear">Limpiar</button></div>
    <div class="assumption">“Relacionar GTIN” solo ofrece productos con costo disponible. “Costo manual” exige una fuente. “Excluir” cuenta como verificado, pero no inventa un margen.</div>
    <div class="table-wrap"><table class="data-table pending-table"><thead><tr><th>Código / producto</th><th>Motivo pendiente</th><th>Meses</th><th>Líneas</th><th>Cantidad</th><th>Importe vendido</th><th>Decisión</th><th>Resultado</th><th>Acción</th></tr></thead><tbody>${page.map(group=>`<tr class="${group.decision?'manual-row':''}"><td><span class="mono">${esc(group.code||'Sin código')}</span><br><b>${esc(group.product)}</b><small class="cell-note">${esc(group.unit)}</small></td><td>${esc(group.reason)}</td><td>${esc(group.months.join(', '))}</td><td class="numeric">${quantity(group.rows.length)}</td><td class="numeric">${quantity(group.qty)}</td><td class="numeric"><b>${money(group.amount)}</b></td><td>${group.decision?group.decision.mode==='cost_gtin'?`GTIN ${esc(group.decision.targetGtin)}<small class="cell-note">${esc(group.decision.targetName)}</small>`:group.decision.mode==='manual_cost'?`${preciseMoney(group.decision.unitCost)}<small class="cell-note">${esc(group.decision.source)}</small>`:`Excluido<small class="cell-note">${esc(group.decision.exclusion)}</small>`:'Sin decisión'}</td><td><span class="tag ${pendingStatusClass(group)}">${pendingStatusLabel(group)}</span>${group.state==='partial'?`<small class="cell-note">${quantity(group.coveredRows)} de ${quantity(group.rows.length)} líneas recuperadas</small>`:''}</td><td><button class="btn ${group.decision?'secondary':''}" data-pending-key="${esc(group.key)}">${group.decision?'Editar':'Resolver'}</button></td></tr>`).join('')||'<tr><td colspan="9">No hay grupos para estos filtros.</td></tr>'}</tbody></table></div>
    <div class="pagination"><span>${quantity(filtered.length)} grupos · página ${pendingView.page+1} de ${pages}</span><div><button id="pendingPrev" ${pendingView.page===0?'disabled':''}>←</button> <button id="pendingNext" ${pendingView.page===pages-1?'disabled':''}>→</button></div></div></div>`;
  $('#pendingStatus').onchange=e=>{pendingView.status=e.target.value;pendingView.page=0;renderPendingReview()};$('#pendingReason').onchange=e=>{pendingView.reason=e.target.value;pendingView.page=0;renderPendingReview()};
  $('#pendingQuery').oninput=e=>{const caret=e.target.selectionStart;pendingView.query=e.target.value;pendingView.page=0;renderPendingReview();$('#pendingQuery').focus();$('#pendingQuery').setSelectionRange(caret,caret)};
  $('#pendingClear').onclick=()=>{Object.assign(pendingView,{status:'pending',reason:'',query:'',page:0});renderPendingReview()};$('#pendingPrev').onclick=()=>{pendingView.page--;renderPendingReview()};$('#pendingNext').onclick=()=>{pendingView.page++;renderPendingReview()};
  document.querySelectorAll('[data-pending-key]').forEach(button=>button.onclick=()=>openPendingDecision(button.dataset.pendingKey));$('#exportPendingJson').onclick=()=>exportPendingJson(groups);$('#exportPendingExcel').onclick=()=>exportPendingExcel(groups);
}
